customCSS:
.t, .history { color: #928374; }
.join { color: #b8bb26; }
.part, .quit { color: #928374; }
.kick, .error { color: #fb4934; }
.notice { color: #fabd2f; }
.action { color: #d3869b; }
.mode, .nick, .topic, .server { color: #8ec07c; }
.highlight { color: #ebdbb2; background-color: #665c54; border-left: 3px solid #d3869b; padding-left: 8px; }
.reply { color: #928374; border-left: 2px solid #83a598; padding-left: 6px; }
.oper { color: #282828; background-color: #fabd2f; }
.reactions { color: #83a598; background-color: #3c3836; }
.card { background-color: #3c3836; border-color: #928374; }
.card-title { color: #83a598; }
.card-desc { color: #928374; }
.daychange { color: #928374; border-color: #3c3836; }
